from pathlib import Pathfrom typing import Dictfrom collections import defaultdictfrom swat_toolkit.swat_calib.utils.data_info import DATAParameterfrom swat_toolkit.swat_calib.io.readers import ReadFileLineclass SWATParam(ReadFileLine):    """    Read and manage SWAT parameter definitions    Examples:        >>> param_file = SWATParam("swatParam.txt")        >>> param = param_file.get("CN2")        >>> print(param.name, param.ext, param.vmin, param.vmax)    """    def __init__(self, param_path):        super().__init__()        self.param_path = Path(param_path)        if not self.param_path.exists():            raise FileNotFoundError(f"Parameter file not found: {param_path}")        self.params = self.__read_param_file(str(param_path))    def get(self, name: str) -> DATAParameter:        # if full name "ESCO.hru" → match        if name in self.params:            return self.params[name]        # if name "ESCO" → find all key match        matches = {k: v for k, v in self.params.items()                   if v.name == name}        if not matches:            raise KeyError(f"Parameter '{name}' not found")        if len(matches) > 1:            keys = list(matches.keys())            raise KeyError(                f"Ambiguous parameter '{name}': found {keys}. "                f"Please specify with ext, e.g. '{keys[0]}'"                )        return next(iter(matches.values()))    def get_params(self, param: list):        param_by_ext = defaultdict(list)        for pname in param:            param_ = self.get(pname)            ext = param_.ext if param_.ext.startswith('.') else f".{param_.ext}"            param_by_ext[ext].append(pname)        return dict(param_by_ext)    def get_param_by_name(self, param_dict: Dict) -> Dict:        param_by_ext = defaultdict(dict)        for pname, value in param_dict.items():            param = self.get(pname)            ext = param.ext if param.ext.startswith('.') else f".{param.ext}"            param_by_ext[ext][pname] = value        return dict(param_by_ext)    def __read_param_file(self, file_path: str) -> Dict:        """Read parameter definition file"""        params = {}        lines = self.__read_file(file_path)        for items in lines:            full_param = items[0]            name, ext = self.__parse_input_name(full_param)            key = f"{name}{ext}"            param = DATAParameter(                    name=name,                    ext=ext,                    line=int(items[1]) - 1,  # Python 0-indexed                    start=int(items[2]) - 1,                    end=int(items[3]),                    round=int(items[4]),                    vmin=float(items[5]),                    vmax=float(items[6])            )            params[key] = param        return params    def __read_file(self, file_path: str):        """Read file and parse lines"""        with open(file_path, 'r', encoding='utf-8') as file:            lines = [self._split_space(line.strip())                     for line in file                     if line.strip() and not line.startswith('!')]        return lines    def __parse_input_name(self, full_name: str):        """Parse parameter name and extension"""        if '.' in full_name:            parts = full_name.rsplit('.', 1)            return parts[0], f".{parts[1]}"  # ('CN2', '.mgt')        return full_name, None    def __repr__(self):        return f"SWATParam(params={len(self.params)})"